//! Instanced views, flatten and mirror-unfold.
//!
//! An [`InstancedView`] stores placements of prototype meshes; [`flatten`] expands it
//! deterministically (ascending instance id) into one mesh; [`unfold`] builds the group
//! generated by a list of (typically mirror) transforms from one reduced mesh.
//!
//! # Welding
//! With `weld_tol`, vertices are merged **across instances only** (a vertex may only be merged
//! into a vertex that existed before its instance was appended; the lowest index within the
//! tolerance wins) and **only boundary vertices** (vertices of a one-cell face of the source) are
//! candidates, so a prototype's own vertices are never merged with each other (baffles stay
//! baffles). Faces that end up with the same vertex cycle as a face of an earlier instance are
//! shared; such a face becomes interior and is reclassified (see [`FlattenOptions::on_merge`]).
//!
//! # What is carried
//! Cells (shape, template corners, lineage), vertices, faces with kinds, classification and
//! linear geometry. Proper transforms also carry high-order cells. Mirroring (or welding)
//! high-order cells is `Unsupported`. Sets, tags, the edge table and face curves are not
//! carried; each is reported as a [`LossNote`] in [`FlattenMap::loss`].

use crate::build::{CellAdded, MeshBuild, SerialAlloc};
use crate::classify::Classification;
use crate::error::{MeshError, Result};
use crate::hierarchy::MeshCatalog;
use crate::highorder::NodeRef;
use crate::index::{CellIx, FaceIx, FaceKind, MeshEntityKind, SignedFace, VertexIx};
use crate::read::MeshRead;
use crate::shape::LoopRelation;
use sm_core::{EntityId, EntityKind, Point3, Transform, Vector3};
use smallvec::SmallVec;
use std::collections::BTreeMap;
use std::ops::Range;

/// One placement of a prototype mesh.
#[derive(Clone, Debug, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
pub struct Instance {
    /// Stable id (`EntityKind::Instance`); flatten order is ascending id.
    pub id: EntityId,
    /// Prototype mesh id (`EntityKind::Mesh`).
    pub prototype: EntityId,
    /// Placement; may be improper (mirrored copy).
    pub transform: Transform,
}

/// An instanced view: prototypes live in the catalog, the view only lists placements.
#[derive(Clone, Debug, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
pub struct InstancedView {
    /// Stable id of the view.
    pub id: EntityId,
    /// Placements.
    pub instances: Vec<Instance>,
}

/// Context handed to [`FlattenOptions::on_merge`] when two classifications must become one.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct MergeCtx {
    /// Whether a face or a vertex is being merged (never `Edge` or `Cell`).
    pub kind: MeshEntityKind,
    /// The classification the entity already has in the target (from the earlier instance).
    pub existing: Classification,
    /// The classification it brings from the instance being appended (after `remap_class`).
    pub incoming: Classification,
    /// Classifications of one cell on each side: `[existing side, incoming side]`.
    pub cells: [Classification; 2],
}

/// A rule resolving a classification merge; see [`FlattenOptions::on_merge`].
pub type MergeRule<'a> = &'a dyn Fn(&MergeCtx) -> Result<Classification>;

/// Options for [`append_transformed`], [`flatten`] and [`unfold`].
#[derive(Default)]
pub struct FlattenOptions<'a> {
    /// Weld boundary vertices of an instance to vertices of earlier instances within this
    /// Chebyshev distance. `None` keeps instances disjoint.
    pub weld_tol: Option<f64>,
    /// Maps `(instance, source classification)` to the classification in the target model
    /// (for example the mirror image of a boundary face). Applied to vertices (welded ones
    /// included), faces and cells. Identity when `None`.
    pub remap_class: Option<&'a dyn Fn(EntityId, Classification) -> Classification>,
    /// Decides the classification of a face that stops being a boundary because it was welded
    /// to a face of an earlier instance, and of a welded vertex that stays on the boundary when
    /// the two classifications differ. Default: for faces, the cells' classification when both
    /// cells agree; for vertices, the existing classification when equal to the incoming one,
    /// and the shared classification of all cells around it when it became interior; otherwise
    /// [`MeshError::ClassConflict`].
    ///
    /// Not consulted when both sides already agree: a welded vertex that stays on the boundary
    /// of the union keeps its classification even if it names a vanished symmetry entity (a
    /// `TopoEdge` where the symmetry face meets the top face, or the axis `TopoVertex` of a
    /// quarter unfold). Fixing those is the caller's job, via `remap_class` or by reclassifying
    /// afterwards; the default output carries such stale model references.
    pub on_merge: Option<MergeRule<'a>>,
}

/// What a flatten or append could not carry over.
#[derive(Clone, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
pub enum LossKind {
    /// A named set was dropped.
    Set(String),
    /// A tag column was dropped.
    Tag(MeshEntityKind, String),
    /// The edge table (and edge classification) was dropped.
    EdgeTable,
    /// This many face curves were dropped.
    FaceCurves(usize),
}

/// One dropped item and the instance it came from.
#[derive(Clone, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
pub struct LossNote {
    /// Instance whose prototype held the item.
    pub instance: EntityId,
    /// What was dropped.
    pub what: LossKind,
}

/// A welded vertex awaiting its final classification (see [`finalize_welds`]).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Weld {
    /// The vertex in the builder that the source vertex was merged into.
    pub vertex: VertexIx,
    /// Source classification after `remap_class`.
    pub incoming: Classification,
    /// Classification of a source cell around the vertex, after `remap_class`.
    pub incoming_cell: Classification,
}

/// Where source entities landed in the builder.
#[derive(Clone, Debug, PartialEq)]
pub struct AppendMap {
    /// Builder vertex for each source vertex.
    pub vertex: Vec<VertexIx>,
    /// Builder (provisional) face for each source face.
    pub face: Vec<FaceIx>,
    /// Builder cell for each source cell.
    pub cell: Vec<CellIx>,
    /// Provisional faces that were shared with an earlier instance (now interior, reclassified).
    pub merged_faces: Vec<FaceIx>,
    /// Welded vertices; pass to [`finalize_welds`] after all instances are appended.
    pub welds: Vec<Weld>,
    /// First provisional face index created by this append.
    pub face_start: usize,
    /// First vertex index created by this append.
    pub vertex_start: usize,
    /// Items not carried over.
    pub loss: Vec<LossKind>,
}

/// Provenance of a flattened mesh.
#[derive(Clone, Debug, PartialEq)]
pub struct FlattenMap {
    /// `(instance, cell range)` in flatten order (ascending instance id, ascending cell index).
    pub cells: Vec<(EntityId, Range<u32>)>,
    /// Per instance: the final vertex of each prototype vertex.
    pub instance_vertices: Vec<(EntityId, Vec<VertexIx>)>,
    /// Per final vertex: the instance and prototype vertex that created it (first wins).
    pub vertex_origin: Vec<(EntityId, VertexIx)>,
    /// Per final face: the instance and prototype face that created it.
    pub face_origin: Vec<(EntityId, FaceIx)>,
    /// Final faces that were welded across instances and reclassified (ascending).
    pub merged_faces: Vec<FaceIx>,
    /// Items not carried over.
    pub loss: Vec<LossNote>,
}

impl FlattenMap {
    /// The instance and prototype-local cell index of a flattened cell.
    pub fn locate(&self, c: CellIx) -> Option<(EntityId, CellIx)> {
        let i = self.cells.partition_point(|(_, r)| r.end <= c.0);
        let (id, r) = self.cells.get(i)?;
        (r.start <= c.0).then(|| (*id, CellIx(c.0 - r.start)))
    }
}

/// Compose two transforms: `compose(a, b)` applies `b` first, then `a`.
pub fn compose(a: &Transform, b: &Transform) -> Transform {
    let mut m = [[0.0; 3]; 3];
    for (i, row) in m.iter_mut().enumerate() {
        for (j, e) in row.iter_mut().enumerate() {
            *e = (0..3).map(|k| a.m[i][k] * b.m[k][j]).sum();
        }
    }
    let t = a.apply_vector(b.t) + a.t;
    Transform { m, t }
}

/// Append a transformed copy of `src` (placed as `instance`) to a builder.
///
/// Orientation is rebuilt from outward loops, so an **improper** transform (mirror, `det < 0`)
/// reverses every face loop and permutes template corners
/// ([`crate::CellShape::reflect_permutation`]); the builder's `finish` re-applies the left/right
/// rule. Welded faces are reclassified here; welded vertices are returned in
/// [`AppendMap::welds`] for [`finalize_welds`].
///
/// **Not atomic**: on `Err` the builder may already hold some of the copy's vertices, faces and
/// cells (`MeshBuild` has no vertex rollback). Discard the builder after an error; `flatten` and
/// `unfold` do, since they take it by value.
pub fn append_transformed<B: MeshBuild>(
    b: &mut B,
    src: &dyn MeshRead,
    instance: EntityId,
    t: &Transform,
    o: &FlattenOptions<'_>,
) -> Result<AppendMap> {
    let remap = |c: Classification| o.remap_class.map_or(c, |f| f(instance, c));
    let improper = t.is_improper();
    let (nv, nf, nc) = (src.vertex_count(), src.face_count(), src.cell_count());
    let co = src.coords();
    let has_ho = (0..nc).any(|c| src.high_order_cell(CellIx::new(c)).is_some());
    if has_ho && (improper || o.weld_tol.is_some()) {
        return Err(MeshError::Unsupported(
            "high-order cells cannot be mirrored or welded in v1".into(),
        ));
    }
    let (vertex_start, face_start) = (b.vertex_count(), b.face_count());

    // Boundary vertices and the first source cell around each vertex.
    let mut on_boundary = vec![false; nv];
    for f in 0..nf {
        if src.face_right(FaceIx::new(f)).is_none() {
            for v in src.face_vertices(FaceIx::new(f)) {
                on_boundary[v.get()] = true;
            }
        }
    }
    let mut first_cell = vec![u32::MAX; nv];
    for c in 0..nc {
        for sf in src.cell_faces(CellIx::new(c)) {
            for v in src.face_vertices(sf.face()) {
                if first_cell[v.get()] == u32::MAX {
                    first_cell[v.get()] = c as u32;
                }
            }
        }
    }

    // Weld targets are boundary vertices of earlier instances only (one-cell faces).
    let mut target_ok = vec![false; vertex_start];
    if o.weld_tol.is_some() {
        for f in 0..face_start {
            let f = FaceIx::new(f);
            if b.face_degree(f) == 1 {
                for v in b.face_loop(f) {
                    target_ok[v.get()] = true;
                }
            }
        }
    }
    let mut vmap = Vec::with_capacity(nv);
    let mut welds = Vec::new();
    for i in 0..nv {
        let p = t.apply_point(co.get(i));
        let merged = match o.weld_tol {
            Some(tol) if on_boundary[i] => b
                .find_vertex(p, tol)
                .filter(|v| v.get() < vertex_start && target_ok[v.get()]),
            _ => None,
        };
        let cls = remap(src.vertex_class(VertexIx::new(i)));
        match merged {
            Some(v) => {
                let cell = src.cell_class(CellIx(first_cell[i]));
                welds.push(Weld {
                    vertex: v,
                    incoming: cls,
                    incoming_cell: remap(cell),
                });
                vmap.push(v);
            }
            None => {
                let v = b.add_vertex(p)?;
                b.set_class(crate::index::MeshEntityRef::Vertex(v), cls)?;
                vmap.push(v);
            }
        }
    }
    let extra: Vec<NodeRef> = (nv..co.len())
        .map(|i| b.add_extra_node(t.apply_point(co.get(i))))
        .collect::<Result<_>>()?;

    let mut fmap = vec![FaceIx(FaceIx::NONE); nf];
    // Per source face: true when the new face's loop runs opposite to the source loop.
    let mut fflip: Vec<Option<bool>> = vec![None; nf];
    let mut cmap = Vec::with_capacity(nc);
    let mut merged_faces = Vec::new();
    for ci in 0..nc {
        let c = CellIx::new(ci);
        let sfs = src.cell_faces(c);
        // Source faces map 1:1 (a topological baffle keeps its two faces). A face is shared
        // only with an earlier instance, and only when that face's side is still free.
        let mut signed: SmallVec<[SignedFace; 6]> = SmallVec::new();
        let mut reused: SmallVec<[bool; 6]> = SmallVec::new();
        for sf in sfs.iter() {
            let sface = sf.face();
            let base = if improper {
                sf.side().flipped()
            } else {
                sf.side()
            };
            let (nf_ix, flip, was) = match fflip[sface.get()] {
                Some(flip) => (fmap[sface.get()], flip, true),
                None => {
                    let l: SmallVec<[VertexIx; 4]> = src
                        .face_vertices(sface)
                        .iter()
                        .map(|v| vmap[v.get()])
                        .collect();
                    // Any earlier face on this cycle with the needed side free (coincident
                    // baffle faces share a cycle); creation order keeps it deterministic.
                    let shared = b
                        .find_face_where(&l, &mut |f, rel| {
                            let side = if rel == LoopRelation::Reversed {
                                base.flipped()
                            } else {
                                base
                            };
                            f.get() < face_start && b.face_cell(f, side).is_none()
                        })
                        .map(|(f, rel)| (f, rel == LoopRelation::Reversed));
                    match shared {
                        Some((f, flip)) => (f, flip, true),
                        None => (b.add_face(&l)?, false, false),
                    }
                }
            };
            fmap[sface.get()] = nf_ix;
            fflip[sface.get()] = Some(flip);
            let side = if flip { base.flipped() } else { base };
            signed.push(SignedFace::new(nf_ix, side));
            reused.push(was);
        }
        let corners: Option<SmallVec<[VertexIx; 8]>> = src.cell_corners(c).map(|ov| {
            let mapped: SmallVec<[VertexIx; 8]> = ov.iter().map(|v| vmap[v.get()]).collect();
            if improper {
                src.cell_shape(c)
                    .reflect_permutation()
                    .iter()
                    .map(|&k| mapped[k as usize])
                    .collect()
            } else {
                mapped
            }
        });
        let added = CellAdded {
            cell: b.add_cell(&signed, corners.as_deref())?,
            faces: signed,
            reused,
        };
        let nc_ix = added.cell;
        let cell_cls = remap(src.cell_class(c));
        b.set_class(crate::index::MeshEntityRef::Cell(nc_ix), cell_cls)?;
        for (i, (sf, &reused)) in sfs.iter().zip(&added.reused).enumerate() {
            let nf_ix = added.faces[i].face();
            fmap[sf.face().get()] = nf_ix;
            let sface = sf.face();
            if !reused {
                b.set_class(
                    crate::index::MeshEntityRef::Face(nf_ix),
                    remap(src.face_class(sface)),
                )?;
                if matches!(
                    src.face_kind(sface),
                    FaceKind::NonConformal | FaceKind::PartitionCut
                ) {
                    b.set_face_kind(nf_ix, src.face_kind(sface))?;
                }
            } else if nf_ix.get() < face_start {
                // Shared with an earlier instance: the face is interior now.
                let other = b
                    .face_cell(nf_ix, added.faces[i].side().flipped())
                    .ok_or_else(|| MeshError::State("merged face lost its cell".into()))?;
                let (existing_cell, incoming_cell) = (
                    b.cell_class(other)
                        .ok_or_else(|| MeshError::State("cell unclassified".into()))?,
                    cell_cls,
                );
                let existing = b.face_class(nf_ix).unwrap_or(existing_cell);
                let incoming = remap(src.face_class(sface));
                let ctx = MergeCtx {
                    kind: MeshEntityKind::Face,
                    existing,
                    incoming,
                    cells: [existing_cell, incoming_cell],
                };
                let new = match o.on_merge {
                    Some(f) => f(&ctx)?,
                    None if existing_cell.entity == incoming_cell.entity => {
                        Classification::on(existing_cell.entity)
                    }
                    None => {
                        return Err(MeshError::ClassConflict(format!(
                            "seam face between cells on {:?} and {:?} needs an on_merge rule",
                            existing_cell.entity, incoming_cell.entity
                        )));
                    }
                };
                b.set_class(crate::index::MeshEntityRef::Face(nf_ix), new)?;
                // The seam is interior now: drop a NonConformal / PartitionCut mark.
                b.set_face_kind(nf_ix, FaceKind::Boundary)?;
                merged_faces.push(nf_ix);
            }
        }
        if let Some(p) = src.cell_parent(c) {
            b.set_cell_parent(nc_ix, cmap[p.get()])?;
        }
        if !src.cell_active(c) {
            b.set_cell_active(nc_ix, false)?;
        }
        if let Some(h) = src.high_order_cell(c) {
            let nodes: Vec<NodeRef> = h
                .nodes
                .iter()
                .map(|n| {
                    if n.get() < nv {
                        NodeRef::Vertex(vmap[n.get()])
                    } else {
                        extra[n.get() - nv]
                    }
                })
                .collect();
            b.set_high_order(nc_ix, h.degree, h.basis, &nodes)?;
        }
        cmap.push(nc_ix);
    }

    let mut loss = Vec::new();
    for s in src.sets() {
        loss.push(LossKind::Set(s.name.clone()));
    }
    for tcol in src.tags() {
        loss.push(LossKind::Tag(tcol.target, tcol.name.clone()));
    }
    if src.edges().is_some() {
        loss.push(LossKind::EdgeTable);
    }
    let curves = (0..nf)
        .filter(|&f| src.face_curve(FaceIx::new(f)).is_some())
        .count();
    if curves > 0 {
        loss.push(LossKind::FaceCurves(curves));
    }
    Ok(AppendMap {
        vertex: vmap,
        face: fmap,
        cell: cmap,
        merged_faces,
        welds,
        face_start,
        vertex_start,
        loss,
    })
}

/// Final classification of welded vertices. Call once after the last [`append_transformed`] and
/// before `finish`.
///
/// A welded vertex that no longer touches any one-cell face is interior to the union and takes
/// the classification shared by all cells around it. One that still lies on the boundary keeps
/// its classification if the two sides agree; otherwise `on_merge` decides, and without it the
/// call fails with [`MeshError::ClassConflict`].
pub fn finalize_welds<B: MeshBuild>(
    b: &mut B,
    welds: &[Weld],
    o: &FlattenOptions<'_>,
) -> Result<()> {
    if welds.is_empty() {
        return Ok(());
    }
    if let Some(w) = welds.iter().find(|w| w.vertex.get() >= b.vertex_count()) {
        return Err(MeshError::State(format!(
            "weld names vertex {:?} that does not exist",
            w.vertex
        )));
    }
    let wanted: std::collections::BTreeSet<VertexIx> = welds.iter().map(|w| w.vertex).collect();
    let mut bnd: BTreeMap<VertexIx, bool> = wanted.iter().map(|&v| (v, false)).collect();
    for f in 0..b.face_count() {
        let f = FaceIx::new(f);
        if b.face_degree(f) == 1 {
            for v in b.face_loop(f) {
                if let Some(x) = bnd.get_mut(v) {
                    *x = true;
                }
            }
        }
    }
    let mut around: BTreeMap<VertexIx, Vec<EntityId>> = BTreeMap::new();
    for c in 0..b.cell_count() {
        let ce = b.cell_class(CellIx::new(c)).map(|c| c.entity);
        let mut vs: SmallVec<[VertexIx; 16]> = SmallVec::new();
        for sf in b.cell_faces(CellIx::new(c)) {
            vs.extend(
                b.face_loop(sf.face())
                    .iter()
                    .copied()
                    .filter(|v| wanted.contains(v)),
            );
        }
        vs.sort_unstable();
        vs.dedup();
        for v in vs {
            if bnd.get(&v) == Some(&false) {
                around.entry(v).or_default().extend(ce);
            }
        }
    }
    for w in welds {
        let existing = b.vertex_class(w.vertex).ok_or(MeshError::Unclassified(
            crate::index::MeshEntity::Vertex(w.vertex),
        ))?;
        let on_bnd = *bnd
            .get(&w.vertex)
            .ok_or_else(|| MeshError::State("weld vertex not tracked".into()))?;
        let result = if !on_bnd {
            let ents = around.get(&w.vertex).ok_or_else(|| {
                MeshError::State(format!("welded vertex {:?} touches no cell", w.vertex))
            })?;
            match ents.split_first() {
                Some((e0, rest)) if rest.iter().all(|e| e == e0) => Classification::on(*e0),
                _ => resolve_vertex(b, w, existing, o)?,
            }
        } else if existing.entity == w.incoming.entity {
            existing
        } else {
            resolve_vertex(b, w, existing, o)?
        };
        if result != existing {
            b.set_class(crate::index::MeshEntityRef::Vertex(w.vertex), result)?;
        }
    }
    Ok(())
}

fn resolve_vertex<B: MeshBuild>(
    b: &B,
    w: &Weld,
    existing: Classification,
    o: &FlattenOptions<'_>,
) -> Result<Classification> {
    let existing_cell = b
        .vertex_cell(w.vertex)
        .and_then(|c| b.cell_class(c))
        .ok_or_else(|| MeshError::State("welded vertex has no cell".into()))?;
    let ctx = MergeCtx {
        kind: MeshEntityKind::Vertex,
        existing,
        incoming: w.incoming,
        cells: [existing_cell, w.incoming_cell],
    };
    match o.on_merge {
        Some(f) => f(&ctx),
        None => Err(MeshError::ClassConflict(format!(
            "welded vertex has classifications {:?} and {:?}; provide an on_merge rule",
            existing.entity, w.incoming.entity
        ))),
    }
}

struct Item<'a> {
    id: EntityId,
    mesh: &'a dyn MeshRead,
    t: Transform,
}

fn flatten_items<B: MeshBuild>(
    items: &[Item<'_>],
    mut b: B,
    o: &FlattenOptions<'_>,
    alloc: &mut SerialAlloc,
) -> Result<(B::Output, FlattenMap)> {
    let mut cells = Vec::with_capacity(items.len());
    let mut inst_vertices = Vec::with_capacity(items.len());
    let mut welds = Vec::new();
    let mut loss = Vec::new();
    let mut merged: Vec<FaceIx> = Vec::new();
    let mut vertex_origin: Vec<(EntityId, VertexIx)> = Vec::new();
    let mut face_origin_prov: Vec<Option<(EntityId, FaceIx)>> = Vec::new();
    for it in items {
        let start = b.cell_count() as u32;
        let am = append_transformed(&mut b, it.mesh, it.id, &it.t, o)?;
        cells.push((it.id, start..b.cell_count() as u32));
        // Origins of entities created by this append.
        vertex_origin.resize(b.vertex_count(), (it.id, VertexIx(0)));
        for (sv, v) in am.vertex.iter().enumerate() {
            if v.get() >= am.vertex_start {
                vertex_origin[v.get()] = (it.id, VertexIx::new(sv));
            }
        }
        face_origin_prov.resize(b.face_count(), None);
        for (sf, f) in am.face.iter().enumerate() {
            if f.get() >= am.face_start && face_origin_prov[f.get()].is_none() {
                face_origin_prov[f.get()] = Some((it.id, FaceIx::new(sf)));
            }
        }
        merged.extend(am.merged_faces);
        welds.extend(am.welds);
        loss.extend(am.loss.into_iter().map(|what| LossNote {
            instance: it.id,
            what,
        }));
        inst_vertices.push((it.id, am.vertex));
    }
    finalize_welds(&mut b, &welds, o)?;
    let fin = b.finish(alloc)?;
    let mut face_origin = vec![
        (
            EntityId::new(EntityKind::Instance, 0).ok_or(MeshError::SerialOverflow)?,
            FaceIx(0)
        );
        face_origin_prov.len()
    ];
    for (p, orig) in face_origin_prov.iter().enumerate() {
        if let Some(orig) = orig {
            face_origin[fin.face_remap[p].get()] = *orig;
        }
    }
    let mut merged_faces: Vec<FaceIx> = merged.iter().map(|f| fin.face_remap[f.get()]).collect();
    merged_faces.sort_unstable();
    merged_faces.dedup();
    Ok((
        fin.mesh,
        FlattenMap {
            cells,
            instance_vertices: inst_vertices,
            vertex_origin,
            face_origin,
            merged_faces,
            loss,
        },
    ))
}

/// Expand an instanced view into one mesh. Instances are placed in ascending id order, so the
/// result is deterministic. With `weld_tol`, abutting instances share vertices and faces
/// (a conforming flatten); otherwise they stay disjoint and meet through interface records.
/// `alloc` is unchanged on `Err`.
pub fn flatten<B: MeshBuild>(
    cat: &dyn MeshCatalog,
    view: EntityId,
    b: B,
    o: &FlattenOptions<'_>,
    alloc: &mut SerialAlloc,
) -> Result<(B::Output, FlattenMap)> {
    let v = cat
        .views()
        .iter()
        .find(|v| v.id == view)
        .ok_or_else(|| MeshError::Hierarchy(format!("unknown view {view:?}")))?;
    let mut insts: Vec<&Instance> = v.instances.iter().collect();
    insts.sort_by_key(|i| i.id);
    let items: Vec<Item<'_>> = insts
        .into_iter()
        .map(|i| {
            Ok(Item {
                id: i.id,
                mesh: cat
                    .mesh(i.prototype)
                    .ok_or(MeshError::UnknownMesh(i.prototype))?,
                t: i.transform,
            })
        })
        .collect::<Result<_>>()?;
    let mut a = alloc.clone();
    let r = flatten_items(&items, b, o, &mut a)?;
    *alloc = a;
    Ok(r)
}

/// Unfold a reduced mesh by a deck of transforms (typically mirrors).
///
/// The result holds the images of `src` under every product of a subset of the deck, applied in
/// deck order: for a deck `[t1, t2]` the images are `src`, `t1(src)`, `t2(src)`, `t2(t1(src))`
/// (image `k` uses `t_i` iff bit `i` of `k` is set). **The deck excludes the identity**, which is
/// always image 0. Each image gets a fresh `Instance` id from `alloc` (ascending with `k`), which
/// is what `remap_class` and the [`FlattenMap`] see. Use `weld_tol` so images touching along the
/// mirror planes share vertices and faces. At most 16 transforms. `alloc` is unchanged on `Err`.
pub fn unfold<B: MeshBuild>(
    src: &dyn MeshRead,
    deck: &[Transform],
    b: B,
    o: &FlattenOptions<'_>,
    alloc: &mut SerialAlloc,
) -> Result<(B::Output, FlattenMap)> {
    if deck.len() > 16 {
        return Err(MeshError::Unsupported(
            "an unfold deck has at most 16 transforms".into(),
        ));
    }
    let mut a = alloc.clone();
    let mut items = Vec::with_capacity(1 << deck.len());
    for k in 0..(1usize << deck.len()) {
        let mut t = Transform::IDENTITY;
        for (i, d) in deck.iter().enumerate() {
            if k >> i & 1 == 1 {
                t = compose(d, &t);
            }
        }
        items.push(Item {
            id: a.one(EntityKind::Instance)?,
            mesh: src,
            t,
        });
    }
    let r = flatten_items(&items, b, o, &mut a)?;
    *alloc = a;
    Ok(r)
}

/// Helper for tests and callers: a point mirrored across the plane with unit normal `n` through `p0`.
pub fn mirror_transform(p0: Point3, n: Vector3) -> Transform {
    let nn = n.dot(n);
    let mut m = [[0.0; 3]; 3];
    let nv = [n.x, n.y, n.z];
    for (i, row) in m.iter_mut().enumerate() {
        for (j, e) in row.iter_mut().enumerate() {
            *e = f64::from(u8::from(i == j)) - 2.0 * nv[i] * nv[j] / nn;
        }
    }
    let q = Vector3::new(p0.x, p0.y, p0.z);
    let mq = Vector3::new(
        m[0][0] * q.x + m[0][1] * q.y + m[0][2] * q.z,
        m[1][0] * q.x + m[1][1] * q.y + m[1][2] * q.z,
        m[2][0] * q.x + m[2][1] * q.y + m[2][2] * q.z,
    );
    Transform { m, t: q - mq }
}
